DEN = 1000000

def words(text):
    out=[tuple(map(int,w)) for w in text.split()]
    assert all(len(w)==5 and all(0<=x<7 for x in w) for w in out)
    return out
core=words(CORE);witness=core+words(FREE_WITNESS)
assert len(core)==len(set(core))==308
assert len(witness)==len(set(witness))==367
for a,b in combinations(witness,2):
    assert any((x-y)%7 in (2,3,4,5) for x,y in zip(a,b))
W=list(product(range(7),repeat=5));blocked={w:0 for w in W}
for w in core:
    for v in product(*[((x-1)%7,x,(x+1)%7) for x in w]):
        blocked[v]+=1
U2={w for w,n in blocked.items() if n<=2}
assert len(U2)==2217 and set(witness)<=U2
raw=zlib.decompress(base64.b85decode(DATA))
assert len(raw)==6156 and hashlib.sha256(raw).hexdigest()=='c539c699a86e25ec4c21ba93567d6862eaf74c17a57e61ca3b25e12eceeaed50'
coverage={w:0 for w in U2};total=0;origins=set()
for index,units in struct.iter_unpack('<HI',raw):
    # Nonnegative cover weights may exceed one; upward rounding preserves coverage.
    assert index<len(W) and units>0 and index not in origins
    origins.add(index);total+=units
    # Every expanded box is a conflict clique.
    for w in product(*[(x,(x+1)%7) for x in W[index]]):
        if w in coverage:coverage[w]+=units
assert len(origins)==1026 and min(coverage.values())>=DEN
assert total==367999845 and total<368*DEN
print('2217 U2 vertices;1026 boxes;weight367999845/1000000<368.')
print('Independent witness367; therefore alpha(U2)=367.')
